def longest_common_prefix(strs):
    if not strs:
        return ""
    shortest_match = len(strs[0])
    for i in range(len(strs)):                                # every string
        for j in range(len(strs)):                              # compared against every other string
            if i == j:
                continue
            k = 0
            while k < len(strs[i]) and k < len(strs[j]) and strs[i][k] == strs[j][k]:
                k += 1
            shortest_match = min(shortest_match, k)
    return strs[0][:shortest_match]


if __name__ == "__main__":
    strs = ["flower", "flow", "flight"]
    print(longest_common_prefix(strs))

