public class Main {
    String longestCommonPrefix(String[] strs) {
        if (strs.length == 0) return "";
        int shortestMatch = strs[0].length();
        for (int i = 0; i < strs.length; i++) {                    // every string
            for (int j = 0; j < strs.length; j++) {                  // compared against every other string
                if (i == j) continue;
                int k = 0;
                while (k < strs[i].length() && k < strs[j].length() && strs[i].charAt(k) == strs[j].charAt(k)) {
                    k++;
                }
                shortestMatch = Math.min(shortestMatch, k);
            }
        }
        return strs[0].substring(0, shortestMatch);
    }

    public static void main(String[] args) {
        String[] strs = {"flower", "flow", "flight"};
        Main solution = new Main();
        System.out.println(solution.longestCommonPrefix(strs));
    }
}

